// ── Shared Primitives ─────────────────────────────────────────────────────────

function StatusBar({ light = false }) {
  const [time, setTime] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);
  const col = light ? "#fff" : C.dark;
  return (
    <div style={{ height: 50, display: "flex", justifyContent: "space-between", alignItems: "center", padding: "0 24px", flexShrink: 0 }}>
      <span style={{ fontSize: 15, fontWeight: 700, color: col }}>
        {String(time.getHours()).padStart(2, "0")}:{String(time.getMinutes()).padStart(2, "0")}
      </span>
      <div style={{ width: 120, height: 30, background: light ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.05)", borderRadius: 20 }} />
      <span style={{ fontSize: 12, color: col, letterSpacing: 2 }}>▲ ● ■</span>
    </div>
  );
}

function TabBar({ active, onNav }) {
  const tabs = [
    { key: S.HOME, icon: "🏠", label: "Home" },
    { key: S.CONTACTS, icon: "👥", label: "Contacts" },
    { key: S.LOCATION, icon: "📍", label: "Location" },
    { key: S.TIPS, icon: "💡", label: "Tips" },
    { key: S.PROFILE, icon: "LOGO", label: "Profile" },
  ];
  return (
    <div style={{ height: 80, background: C.white, borderTop: `1px solid ${C.gray}`, display: "flex", alignItems: "center", justifyContent: "space-around", padding: "0 8px 12px", flexShrink: 0, boxShadow: "0 -8px 24px rgba(107,33,200,0.07)" }}>
      {tabs.map((t) => {
        const on = active === t.key;
        return (
          <div key={t.key} onClick={() => onNav(t.key)} style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, cursor: "pointer", padding: "8px 16px", borderRadius: 16, background: on ? C.softPurple : "transparent", minWidth: 60 }}>
            {t.icon === "LOGO"
              ? <img src={LOGO_IMG} alt="Profile" style={{ width: 26, height: 26, objectFit: "contain", opacity: on ? 1 : 0.5 }} />
              : <span style={{ fontSize: 22 }}>{t.icon}</span>
            }
            <span style={{ fontSize: 11, fontWeight: 700, color: on ? C.purple : C.grayText }}>{t.label}</span>
          </div>
        );
      })}
    </div>
  );
}

function BackHeader({ title, subtitle, onBack, gradient }) {
  return (
    <div style={{ background: gradient || `linear-gradient(160deg, ${C.purple} 0%, ${C.purpleMid} 100%)`, padding: "0 24px 24px", borderBottomLeftRadius: 32, borderBottomRightRadius: 32, flexShrink: 0 }}>
      <StatusBar light />
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div onClick={onBack} style={{ width: 36, height: 36, borderRadius: 18, background: "rgba(255,255,255,0.2)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, color: "#fff", cursor: "pointer", flexShrink: 0 }}>←</div>
        <div>
          <div style={{ fontSize: 20, fontWeight: 900, color: "#fff" }}>{title}</div>
          {subtitle && <div style={{ fontSize: 12, color: "rgba(255,255,255,0.75)", marginTop: 2 }}>{subtitle}</div>}
        </div>
      </div>
    </div>
  );
}

function Toggle({ value, onChange, color = C.purple }) {
  return (
    <div onClick={() => onChange(!value)} style={{ width: 50, height: 28, borderRadius: 14, background: value ? color : "#D1D5DB", position: "relative", cursor: "pointer", transition: "background 0.25s", flexShrink: 0 }}>
      <div style={{ position: "absolute", top: 3, left: value ? 25 : 3, width: 22, height: 22, borderRadius: 11, background: "#fff", transition: "left 0.25s", boxShadow: "0 2px 6px rgba(0,0,0,0.2)" }} />
    </div>
  );
}

function SettingRow({ icon, label, sublabel, value, onChange, type = "toggle", onPress, color, danger }) {
  return (
    <div onClick={type === "nav" ? onPress : undefined} style={{ background: C.white, borderRadius: 16, padding: "14px 16px", display: "flex", alignItems: "center", gap: 14, marginBottom: 10, cursor: type === "nav" ? "pointer" : "default", boxShadow: "0 2px 10px rgba(107,33,200,0.06)" }}>
      <div style={{ width: 40, height: 40, borderRadius: 13, background: (color || C.purple) + "22", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, flexShrink: 0 }}>{icon}</div>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: danger ? C.danger : C.dark }}>{label}</div>
        {sublabel && <div style={{ fontSize: 12, color: C.grayText, marginTop: 2 }}>{sublabel}</div>}
      </div>
      {type === "toggle" && <Toggle value={value} onChange={onChange} color={color || C.purple} />}
      {type === "nav" && <span style={{ color: C.grayText, fontSize: 18 }}>›</span>}
    </div>
  );
}

function SectionLabel({ text }) {
  return (
    <div style={{ fontSize: 12, fontWeight: 800, color: C.grayText, textTransform: "uppercase", letterSpacing: 1.2, marginBottom: 8, marginTop: 4, paddingLeft: 4 }}>{text}</div>
  );
}

// ── SPLASH ────────────────────────────────────────────────────────────────────

function SplashScreen({ onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2600);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 20, background: `linear-gradient(160deg, ${C.purple} 0%, #9B1FBC 50%, ${C.pink} 100%)` }}>
      <style>{`
        @keyframes shieldPulse { 0%,100%{transform:scale(1) rotate(-2deg)} 50%{transform:scale(1.08) rotate(2deg)} }
        @keyframes glow { 0%,100%{opacity:0.4} 50%{opacity:0.8} }
      `}</style>
      <div style={{ animation: "shieldPulse 2s ease-in-out infinite" }}>
        <ShieldHerLogo size={120} />
      </div>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 38, fontWeight: 900, color: "#fff", letterSpacing: -1, textShadow: "0 2px 16px rgba(0,0,0,0.3)" }}>
          Shield<span style={{ color: C.pinkLight }}>Her</span>
        </div>
        <div style={{ fontSize: 14, color: "rgba(255,255,255,0.85)", marginTop: 8, fontWeight: 500, letterSpacing: 0.5 }}>Smart Safety. Stronger Together.</div>
      </div>
      <div style={{ marginTop: 32, display: "flex", gap: 8 }}>
        {[0, 1, 2].map((i) => (
          <div key={i} style={{ width: i === 1 ? 28 : 8, height: 8, borderRadius: 4, background: i === 1 ? C.white : "rgba(255,255,255,0.35)", transition: "all 0.3s" }} />
        ))}
      </div>
    </div>
  );
}

// ── ONBOARDING ────────────────────────────────────────────────────────────────

function OnboardingScreen({ onDone }) {
  const [step, setStep] = useState(0);
  const s = ONBOARDING_STEPS[step];
  const isLast = step === ONBOARDING_STEPS.length - 1;
  return (
    <div style={{ flex: 1, display: "flex", flexDirection: "column", background: C.bg }}>
      <StatusBar />
      <div style={{ flex: 1, display: "flex", flexDirection: "column", padding: "24px 28px 0" }}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 28, textAlign: "center" }}>
          <div style={{ width: 140, height: 140, borderRadius: 40, background: `linear-gradient(135deg,${s.color}22,${s.color}44)`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 64, border: `2px solid ${s.color}33`, boxShadow: `0 20px 40px ${s.color}22` }}>{s.icon}</div>
          <div>
            <div style={{ fontSize: 30, fontWeight: 900, color: C.dark, lineHeight: 1.2, marginBottom: 16, whiteSpace: "pre-line" }}>{s.title}</div>
            <div style={{ fontSize: 15, color: C.grayText, lineHeight: 1.6, maxWidth: 280 }}>{s.desc}</div>
          </div>
        </div>
        <div style={{ display: "flex", justifyContent: "center", gap: 8, marginBottom: 24 }}>
          {ONBOARDING_STEPS.map((_, i) => (
            <div key={i} style={{ width: i === step ? 28 : 8, height: 8, borderRadius: 4, background: i === step ? s.color : C.gray, transition: "all 0.3s" }} />
          ))}
        </div>
      </div>
      <div style={{ padding: "0 28px 40px", display: "flex", gap: 12 }}>
        {step > 0 && (
          <button onClick={() => setStep(step - 1)} style={{ flex: 1, height: 52, borderRadius: 16, border: `2px solid ${C.purple}`, background: "transparent", color: C.purple, fontSize: 15, fontWeight: 700, cursor: "pointer", fontFamily: "inherit" }}>Back</button>
        )}
        <button onClick={() => isLast ? onDone() : setStep(step + 1)} style={{ flex: 2, height: 52, borderRadius: 16, border: "none", background: `linear-gradient(90deg,${C.purple},${C.pink})`, color: "#fff", fontSize: 16, fontWeight: 800, cursor: "pointer", fontFamily: "inherit", boxShadow: `0 8px 24px ${C.purple}44` }}>
          {isLast ? "Get Protected 🛡️" : "Next →"}
        </button>
      </div>
    </div>
  );
}

