          <div style={{ width: 90, height: 90, borderRadius: 45, background: `linear-gradient(135deg,${C.purple}33,${C.pink}33)`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 46, border: `3px solid ${C.purpleLight}`, marginBottom: 12 }}>👩</div>
