              <div key={bt} onClick={() => setBlood(bt)} style={{ padding: "8px 16px", borderRadius: 10, background: blood === bt ? C.purple : C.softPurple, color: blood === bt ? "#fff" : C.purple, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>{bt}</div>
