            <button onClick={() => setCountdown(Math.max(1, countdown - 1))} style={{ width: 40, height: 40, borderRadius: 12, border: `2px solid ${C.gray}`, background: C.white, fontSize: 20, cursor: "pointer" }}>−</button>
