function HistoryScreen({ onBack }) {
  const [filter, setFilter] = useState("All");
  const all = [
    { type: "Journey", label: "School → Home", date: "Today, 3:22 PM", status: "Arrived safely", icon: "🗺️", color: C.blue },
    { type: "SOS", label: "SOS Alert Triggered", date: "Yesterday, 11:05 PM", status: "Contacts alerted", icon: "🚨", color: C.pink },
    { type: "CheckIn", label: "Check-In Timer", date: "Yesterday, 8:00 AM", status: "Completed", icon: "⏱️", color: C.purple },
    { type: "Journey", label: "Market → Hostel", date: "2 days ago", status: "Arrived safely", icon: "🗺️", color: C.blue },
    { type: "Recording", label: "Audio Evidence", date: "3 days ago", status: "Saved locally", icon: "🎙️", color: C.purpleMid },
    { type: "CheckIn", label: "Night Walk Timer", date: "4 days ago", status: "Auto-alert sent", icon: "⏱️", color: C.warning },
    { type: "Journey", label: "Work → Home", date: "5 days ago", status: "Arrived safely", icon: "🗺️", color: C.blue },
    { type: "SOS", label: "SOS Cancelled", date: "1 week ago", status: "Cancelled in countdown", icon: "🚨", color: C.grayText },
  ];
  const filters = ["All", "Journey", "SOS", "CheckIn", "Recording"];
  const filtered = filter === "All" ? all : all.filter((h) => h.type === filter);
  return (
    <div style={{ flex: 1 }}>
      <BackHeader title="Activity History" subtitle="Your safety journey log" onBack={onBack} />
      <div style={{ padding: "16px 20px 0" }}>
        <div style={{ display: "flex", gap: 8, overflowX: "auto", paddingBottom: 4 }}>
          {filters.map((f) => (
            <div key={f} onClick={() => setFilter(f)} style={{ padding: "7px 16px", borderRadius: 20, cursor: "pointer", background: filter === f ? C.purple : C.softPurple, color: filter === f ? "#fff" : C.purple, fontSize: 13, fontWeight: 700, whiteSpace: "nowrap", flexShrink: 0 }}>{f}</div>
          ))}
        </div>
      </div>
      <div style={{ padding: "16px 20px", overflowY: "auto" }}>
        {filtered.map((h, i) => (
          <div key={i} style={{ background: C.white, borderRadius: 16, padding: "14px 16px", display: "flex", alignItems: "center", gap: 14, marginBottom: 10, boxShadow: "0 2px 10px rgba(107,33,200,0.06)" }}>
            <div style={{ width: 42, height: 42, borderRadius: 14, background: h.color + "22", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>{h.icon}</div>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 14, fontWeight: 700, color: C.dark }}>{h.label}</div>
              <div style={{ fontSize: 12, color: h.color, fontWeight: 600 }}>{h.status}</div>
              <div style={{ fontSize: 11, color: C.grayText, marginTop: 2 }}>{h.date}</div>
            </div>
            {h.type === "Recording" && (
              <div style={{ padding: "4px 10px", borderRadius: 8, background: C.softPurple, color: C.purple, fontSize: 11, fontWeight: 700, cursor: "pointer" }}>▶ Play</div>
            )}
          </div>
        ))}
        {filtered.length === 0 && (
          <div style={{ textAlign: "center", color: C.grayText, padding: "40px 0", fontSize: 14 }}>No {filter} records found.</div>
        )}
        <div style={{ height: 16 }} />
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════
// MAIN APP
// ═══════════════════════════════════════════════════════════

const MAIN_TABS = [S.HOME, S.CONTACTS, S.LOCATION, S.TIPS, S.PROFILE];

export default function App() {
  const [screen, setScreen] = useState(S.SPLASH);
  const nav = (s) => setScreen(s);
  const showTab = MAIN_TABS.includes(screen);

  const renderScreen = () => {
    switch (screen) {
      case S.SPLASH:                return <SplashScreen onDone={() => nav(S.ONBOARDING)} />;
      case S.ONBOARDING:            return <OnboardingScreen onDone={() => nav(S.HOME)} />;
      case S.HOME:                  return <HomeScreen onNav={nav} onSOS={() => nav(S.SOS_ACTIVE)} />;
      case S.CONTACTS:              return <ContactsScreen />;
      case S.LOCATION:              return <LocationScreen />;
      case S.TIPS:                  return <TipsScreen />;
      case S.PROFILE:               return <ProfileScreen onNav={nav} />;
      case S.SOS_ACTIVE:            return <SOSActiveScreen onCancel={() => nav(S.HOME)} onSafe={() => nav(S.HOME)} />;
      case S.FAKE_CALL:             return <FakeCallScreen onBack={() => nav(S.HOME)} />;
      case S.JOURNEY:               return <JourneyScreen onBack={() => nav(S.HOME)} />;
      case S.CHECKIN:               return <CheckInScreen onBack={() => nav(S.HOME)} />;
      case S.EDIT_PROFILE:          return <EditProfileScreen onBack={() => nav(S.PROFILE)} />;
      case S.EMERGENCY_SETTINGS:    return <EmergencySettingsScreen onBack={() => nav(S.PROFILE)} />;
      case S.TRIGGER_METHODS:       return <TriggerMethodsScreen onBack={() => nav(S.PROFILE)} />;
      case S.NOTIFICATION_SETTINGS: return <NotificationSettingsScreen onBack={() => nav(S.PROFILE)} />;
      case S.PRIVACY_SECURITY:      return <PrivacySecurityScreen onBack={() => nav(S.PROFILE)} />;
      case S.HELP_SUPPORT:          return <HelpSupportScreen onBack={() => nav(S.PROFILE)} />;
      case S.ABOUT:                 return <AboutScreen onBack={() => nav(S.PROFILE)} />;
      case S.HISTORY:               return <HistoryScreen onBack={() => nav(S.PROFILE)} />;
      default:                      return null;
    }
  };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { background: linear-gradient(135deg, #F3E8FF 0%, #FCE7F3 100%); min-height: 100vh; display: flex; align-items: center; justify-content: center; }
        ::-webkit-scrollbar { display: none; }
        input, textarea, button, select { font-family: 'Nunito', sans-serif; }
      `}</style>
      <div style={{ fontFamily: "'Nunito', sans-serif", minHeight: "100vh", display: "flex", justifyContent: "center", alignItems: "center" }}>
        <div style={{ width: 390, height: 844, background: C.white, borderRadius: 44, overflow: "hidden", position: "relative", boxShadow: "0 40px 80px rgba(107,33,200,0.25), 0 0 0 2px rgba(107,33,200,0.15)", display: "flex", flexDirection: "column" }}>
          <div style={{ flex: 1, overflowY: "auto", overflowX: "hidden", display: "flex", flexDirection: "column" }}>
            {renderScreen()}
          </div>
          {showTab && <TabBar active={screen} onNav={nav} />}
        </div>
      </div>
    </>
  );
}
